----------------------------------
---- BIND PARSER & APPLIER    ----
----------------------------------

local final_binds_config = {}

-- Loop through categories -> subgroups -> binds
for _, category in ipairs(keybindings.categories) do
	if category.subgroups then
		for _, subgroup in ipairs(category.subgroups) do
			if subgroup.binds then
				for _, b in ipairs(subgroup.binds) do
					local modStr = b.mod or ""
					local actionStr = b.action or ""

					-- 1. Replace $variables with their values from keybindings.variables
					for varName, varValue in pairs(keybindings.variables) do
						-- Escape the '$' for Lua's pattern matching
						modStr = string.gsub(modStr, "%$" .. varName, varValue)
						actionStr = string.gsub(actionStr, "%$" .. varName, varValue)
					end

					-- 2. Format the string for Hyprland
					local bindString
					if string.match(b.type, "d") and b.desc then
						-- Types with descriptions (bindd, binddm, etc) format: MOD, KEY, DESCRIPTION, ACTION
						bindString = string.format("%s, %s, %s, %s", modStr, b.key, b.desc, actionStr)
					else
						-- Standard format: MOD, KEY, ACTION
						bindString = string.format("%s, %s, %s", modStr, b.key, actionStr)
					end

					-- 3. Group them by their specific bind type (bind, bindd, bindm, bindde, etc.)
					if not final_binds_config[b.type] then
						final_binds_config[b.type] = {}
					end

					table.insert(final_binds_config[b.type], bindString)
				end
			end
		end
	end
end

-- 4. Pass the entire formatted table to Hyprland to actually apply them
hl.config(final_binds_config)
